import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易附錄纂注卷十一","description":"易附錄纂注 - 易附錄纂注卷十一","frontmatter":{"title":"易附錄纂注卷十一","description":"易附錄纂注 - 易附錄纂注卷十一"},"headers":[],"relativePath":"classics/yifulu-zuanzhu/012.md","filePath":"classics/yifulu-zuanzhu/012.md"}'),r={name:"classics/yifulu-zuanzhu/012.md"};function i(c,a,o,u,d,p){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附錄纂注卷十一",tabindex:"-1"},[n("易附錄纂注卷十一 "),e("a",{class:"header-anchor",href:"#易附錄纂注卷十一","aria-label":"Permalink to “易附錄纂注卷十一”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"元胡一桂撰總論序卦 問：「序卦，或謂非聖人之書，信乎？」曰：「此沙隨程氏之說也。先懦以為非聖人之縕，某以為謂之非易之精則可，謂非易之縕則不可。周子分精與縕字甚分明。序卦卻正是易之縕，事事夾雜，有在裡面。」問：「何謂易之精？」曰：「如易有太極，精是生兩儀，兩儀生四象，四象生八卦，這便是易之問。如序卦中亦見消長進退之義，喚做不是精不得。」曰：「此正是事事夾雜，有在裡面，正是縕。須是自一個生出來，以至於無窮，便是精。」道夫。 纂注 程子曰：乾、坤，天地之道，陰陽之本，故為上篇之首。坎、離，陰陽之成質，故為上篇之終。鹹、恆，夫婦之道，生育之本，故為下篇之首。未濟，坎、離之合；既濟，坎、離之交，合而交，則生物，陰陽之功也，故為下篇之終。二篇之卦既分，而後推其義而為之次，序卦是也。",-1),e("p",null,"有天地，然後萬物生焉。盈天地之間者唯萬物，故受之以屯；屯者，盈也；屯者，物之始生也。物生必蒙，故受之以蒙；蒙者，蒙也，物之稚也。物稚不可不養也，故受之以需；需者，飲食之道也。飲食必有訟，故受之以訟。訟必有眾起，故受之以師；師者，眾也。眾必有所比，故受之以比；比者，比也。比必有所畜，故受之以小畜。物畜然後有禮，故受之以履。履而泰，然後安，故受之以泰； 晁氏雲：鄭無「而泰」二字。 「泰」者，通也。物不可以終通，故受之以否。物不可以終否，故受之以同人。與人同者，物必歸焉，故受之以大有。有大者不可以盈，故受之以謙。有大而能謙必豫，故受之以豫。豫必有隨，故受之以隨。以喜隨人者必有事，故受之以蠱；蠱者，事也。有事而後可大，故受之以臨；臨者，大也。物大然後可觀，故受之以觀。可觀而後有所合，故受之以「噬嗑」。嗑者，合也。物不可以苟合而已，故受之以賁。賁者，飾也。致飾然後亨則盡矣，故受之以剝。剝者，剝也。物不可以終盡，剝窮上反下，故受之以復。復則不妄矣，故受之以「無妄」。有無妄然後可畜，故受之以大畜。物畜然後可養，故受之以頤。頤者，養也。不養則不可動，故受之以大過。附錄。 問：不養則不可動，故受之以大過，何也？曰：動則過矣，故小過亦曰：「有其信者必行之，故受之以小過」。道夫 物不可以終過，故受之以坎。坎者，陷也。陷必有所麗，故受之以離。離者，麗也。 右上篇。 有天地然後有萬物，有萬物然後有男女，有男女然後有夫婦，有夫婦然後有父子，有父子然後有君臣，有君臣然後有上下，有上下然後禮義有所錯。附錄。 問：「序卦中六十四卦獨不言鹹，何也？」曰：「夫婦之道即鹹也。」曰：「亦如上經不言乾、坤，但言天地，則乾、坤可見否？」曰：「然。」道夫。 夫婦之道，不可以不久也，故受之以恆，恆者，久也。物不可以久居其所，故受之以遁，遁者，退也。物不可以終遁，故受之以大壯。物不可以終壯，故受之以晉。附錄。 問：「物不可以終壯，故受之以晉。傳曰：物無壯而終止之理，既壯盛則必進。竊意物進而後至於壯盛，既壯盛則衰退繼之矣。今曰壯盛則必進，此義如何？」曰：「物固有壯而後進者，亦有進而後壯者，其義自有不同。此各隨其事而言，難以一說拘也。且以十二月卦論，大壯之為夬，夬之為乾，豈非壯而後進乎？至乾乃極而衰耳。」又問：「壯與晉何別？」曰：「不但如此壯而已，又更須進一步也。」道夫。 晉者，進也。進必有所傷，故受之以明夷，夷者，傷也。傷於外者，必反其家，故受之以家人。家道窮必乖，故受之以「睽」，睽者，乖也。乖必有難，故受之以「蹇」，蹇者，難也。物不可以終難，故受之以「解」；解者，緩也。緩必有所失。附錄。 問：「緩」字恐不是遲緩之「緩」，乃是懈怠之意，故曰：「解，緩也」。曰：「緩」字是散意。道夫。 故受之以「損」。損而不已必益，故受之以「益」。益而不已必決，故受之以「夬」；夬者，決也。決必有所遇，故受之以「姤」；姤者，遇也。物相遇而後聚，故受之以「萃」；萃者，聚也。聚而上者謂之升，故受之以「升」。升而不已必困，故受之以「困」。困乎上者必反下，故受之以「井」。井道不可不革，故受之以「革」。革物者莫若鼎，故受之以「鼎」。主器者莫若長子，故受之以「震」；震者，動也。物不可以終動，止之，故受之以「艮」；艮者，止也。物不可以終止，故受之以「漸」；漸者，進也。進必有所歸，故受之以「歸妹」。得其所歸者必大，故受之以「豐」；豐者，大也。窮大者必失其居，故受之以「旅」。旅而無所容，故受之以「巽」；巽者，入也。入而後說之，故受之以「兌」；兌者，說也。說而後散之，故受之以「渙」，渙者，離也。物不可以終離，故受之以「節」。節而信之，故受之以「中孚」。有其信者必行之，故受之以「小過」。有過物者必濟，故受之以既濟。物不可窮也，故受之以未濟終焉。 右下篇 易附錄纂注卷十一。",-1)])])}const _=t(r,[["render",i]]);export{m as __pageData,_ as default};
